SELECT COUNT(*)
FROM t_i18n_key
WHERE namespace_id = #{namespaceId}

SELECT COUNT(*)
FROM t_i18n_key k
WHERE k.application_id = #{applicationId}
  AND (k.update_time > #{since}
    OR EXISTS (SELECT 1 FROM t_i18n_translation t WHERE t.key_id = k.key_id AND t.update_time > #{since}))

mapper.update:
UPDATE t_i18n_key
SET source_text = #{next.sourceText}, description = #{next.description},
    source_revision = #{next.sourceRevision}, status = #{next.status}, version = version + 1,
    updated_by = #{next.updatedBy}, update_time = #{next.updateTime}
WHERE key_id = #{row.keyId} AND version = #{row.version}
